import axios from "axios";

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000";

const apiClient = axios.create({
  baseURL: API_BASE_URL,
  headers: { "Content-Type": "application/json" },
  timeout: 10000,
});

export const api = {
  async getHealth() {
    try {
      return await apiClient.get("/health").then(r => r.data);
    } catch (error) {
      console.error("Erro:", error);
      throw error;
    }
  },

  async getMedicina(endpoint: string) {
    return await apiClient.get(`/medicina/${endpoint}`).then(r => r.data);
  },

  async getJuridico(endpoint: string) {
    return await apiClient.get(`/juridico/${endpoint}`).then(r => r.data);
  },
};

export default apiClient;
